// v0.5.0-beta.13.12 起：tab/按钮 emoji → 语义 SVG（TopologyIcon/TeamIcon）。
// v0.5.0-beta.13.13（13.12 装验 T10「这版最好把所有 emoji 都换到对应的
// SVG」）：全量图标库——HarmonyOS 系统图标集（ic_public_*，用户提供的开源素材，
// 24×24 fill 路径直接内联，currentColor 着色）+ 手写 stroke 图标（脑/雷达/
// 闪电/灯泡等 HarmonyOS 无对应件）。
// 纯内联 SVG（无 @ant-design/icons 依赖——插件不装该包），currentColor 随
// 文字色（tab 激活态自动变色）。

import type * as ReactNS from "react";

const host = window.QwenPaw.host;
const React: typeof ReactNS = host.React;

export interface IconProps {
  size?: number;
  style?: ReactNS.CSSProperties;
  className?: string;
}

/** HarmonyOS fill 路径图标工厂（24 viewBox，多 path 支持）。 */
function makeFilled(paths: string[], displayName: string) {
  function Cmp({ size = 14, style, className }: IconProps) {
    return React.createElement(
      "svg",
      {
        viewBox: "0 0 24 24",
        width: size,
        height: size,
        fill: "currentColor",
        style: { verticalAlign: "-2px", flexShrink: 0, ...style },
        className,
        "aria-hidden": true,
      },
      ...paths.map((d, i) => React.createElement("path", { key: i, d })),
    );
  }
  Cmp.displayName = displayName;
  return Cmp;
}


/** 拓扑（DAG）：1 根节点 → 2 子节点，连线 + 圆点（非层级树——
 *  子节点之间无连线，留「可汇合」语义）。 */
export function TopologyIcon({ size = 14, style }: IconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 16 16"
      fill="none"
      style={{ verticalAlign: "-2px", flexShrink: 0, ...style }}
      aria-hidden
    >
      <path
        d="M8 3.2 3.6 11M8 3.2 12.4 11"
        stroke="currentColor"
        strokeWidth="1.4"
        strokeLinecap="round"
      />
      <circle cx="8" cy="2.6" r="1.9" fill="currentColor" />
      <circle cx="3.4" cy="12.2" r="1.9" fill="currentColor" />
      <circle cx="12.6" cy="12.2" r="1.9" fill="currentColor" />
    </svg>
  );
}

/** 团队（双人重叠）：左人实心 + 右人后移半透明重叠（"两人一组"）。 */
export function TeamIcon({ size = 14, style }: IconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 16 16"
      fill="none"
      style={{ verticalAlign: "-2px", flexShrink: 0, ...style }}
      aria-hidden
    >
      {/* 后侧人（右，半透明） */}
      <circle cx="10.6" cy="5" r="2.1" fill="currentColor" opacity="0.45" />
      <path
        d="M13.8 13.4c0-2.2-1.4-3.6-3.2-3.6-.5 0-1 .1-1.4.3"
        stroke="currentColor"
        strokeWidth="1.4"
        strokeLinecap="round"
        opacity="0.45"
      />
      {/* 前侧人（左，实心） */}
      <circle cx="6" cy="5.4" r="2.5" fill="currentColor" />
      <path
        d="M2.2 13.8c0-2.7 1.7-4.4 3.8-4.4s3.8 1.7 3.8 4.4"
        fill="currentColor"
      />
    </svg>
  );
}


